const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY = '<REDACTED_SUPABASE_JWT>';
const H = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const now = new Date();
const DAY = 86400000;
const _d0 = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const weekEnd = new Date(_d0.getTime() - ((_d0.getUTCDay() - 4 + 7) % 7) * DAY);
const weekStart = new Date(weekEnd.getTime() - 7 * DAY);
const since = weekStart.toISOString();
const until = weekEnd.toISOString();
const sel = 'activity_id,post_url,text,posted_at,companyName,totalReactions,comments,reshares,is_reshare,title';
const url = SB + '/linkedin_posts?select=' + sel +
  '&companyName=neq.NONE&companyName=not.is.null' +
  '&posted_at=gte.' + encodeURIComponent(since) +
  '&posted_at=lt.' + encodeURIComponent(until) +
  '&order=posted_at.desc&limit=200';
const raw = await this.helpers.httpRequest({ method: 'GET', url, headers: H, json: true });
const rows = Array.isArray(raw) ? raw : [];
const seen = new Set();
const posts = [];
for (const r of rows) {
  const id = String(r.activity_id || '');
  if (id && seen.has(id)) continue;
  if (id) seen.add(id);
  posts.push({
    idx: posts.length,
    company: r.companyName,
    posted_at: r.posted_at,
    reactions: Number(r.totalReactions) || 0,
    comments: Number(r.comments) || 0,
    reshares: Number(r.reshares) || 0,
    is_reshare: !!r.is_reshare,
    url: r.post_url || '',
    source_id: id || null,
    text: String(r.text || '').replace(/\s+/g, ' ').slice(0, 600),
  });
}
if (!posts.length) return [];
const period_start = weekStart.toISOString().slice(0, 10);
const promptPosts = posts.map(p => ({
  idx: p.idx, company: p.company, posted_at: p.posted_at,
  reactions: p.reactions, comments: p.comments, reshares: p.reshares,
  is_reshare: p.is_reshare, text: p.text,
}));
const openaiBody = {
  model: 'gpt-4.1',
  temperature: 0.3,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: "You are a competitive-intelligence marketing analyst for Twine Security, an identity-security startup (non-human identity / IAM / agentic identity). Each week you review competitors' LinkedIn posts and produce the \"Posts of Interest\" digest the marketing team walks in its review meeting.\n\nYou are given a JSON array of competitor posts from the past week (each has idx, company, posted_at, engagement counts, is_reshare, and truncated text). Reproduce the team's manual curation exactly:\n\n1. SELECT only the strategically notable posts. A post makes the list only if it shows a deliberate, resourced, or novel go-to-market move worth noticing, benchmarking, or copying: a released asset (guide/report/video/infographic), a product/funding/partnership announcement, third-party or earned coverage, an award, real spend (booths/billboards/events), a positioning or messaging shift, an executive amplification chain, an engagement outlier for the company's size, or a tactical detail worth stealing. When a post is borderline, keep it only if you can name a concrete reason; otherwise drop it.\n2. COLLAPSE repetitive posting into a single line. If a company made several near-identical posts (e.g. seven Identiverse booth posts), emit ONE entry with collapsed_count set to the number, idx set to the list of their indices, and a summary that says so.\n3. REJECT the unremarkable silently: routine reposts, generic event RSVPs with no angle, off-category noise, and non-milestones nobody would care about. Do not echo rejected posts.\n4. For each selected line write: \n   - summary: terse, present-tense, house style '<Company> <verb> \"<exact title in quotes>\"' (e.g. 'Lumos releases Identity Agent Force and advertises all their agents'). Describe the artifact/action, not a paraphrase of the body.\n   - post_type: exactly ONE of: Thought Leadership, Event, Webinar, Campaign, Video, Award, Earned Media, Exec Commentary, Networking Event, Product, Partnership, Research, Positioning Shift, Funding, Distribution Tactic, Hiring, Milestone, Customer Story, Seasonal, Community, Interactive, Post.\n   - relevance_reason: one sentence naming why it is on the list.\n   - strategic_angle: one-two sentences of what this means for Twine and a concrete suggested response, in the voice of a marketer briefing the team. This is the most important field: be specific and actionable, never generic.\n   - primary_idx: the idx of the single post whose url/engagement best represents the line (for collapsed lines, pick the strongest one).\n\nBe selective: a good week is ~15-25 lines, not everything. Return ONLY a JSON object of the form {\"selected\":[{\"idx\":<int or [ints]>,\"primary_idx\":<int>,\"company\":<string>,\"post_type\":<string>,\"summary\":<string>,\"relevance_reason\":<string>,\"strategic_angle\":<string>,\"collapsed_count\":<int>}]} with no prose." },
    { role: 'user', content: 'Competitor posts from the past week (JSON):\n' + JSON.stringify(promptPosts) },
  ],
};
return [{ json: { period_start, count: posts.length, posts, openaiBody } }];

const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY = '<REDACTED_SUPABASE_JWT>';
const H = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' };
const llm = $input.first().json;
let content = '';
if (llm && llm.choices && llm.choices[0] && llm.choices[0].message) content = llm.choices[0].message.content || '';
else if (llm && llm.message && llm.message.content) content = llm.message.content;
else if (typeof llm === 'string') content = llm;
let parsed = { selected: [] };
try { parsed = JSON.parse(content); } catch (e) { parsed = { selected: [] }; }
const selected = Array.isArray(parsed.selected) ? parsed.selected : [];
const src = $('Fetch Attributed Posts').first().json;
const posts = (src && src.posts) || [];
const period_start = src && src.period_start;
const byIdx = new Map(posts.map(p => [p.idx, p]));
let tasteByIdx = {};
try { tasteByIdx = $('RAG Taste + Build Prompt').first().json.tasteByIdx || {}; } catch (e) { tasteByIdx = {}; }
// Canonical taxonomy — the LLM occasionally drifts (e.g. 'Guide'); map strays
// to the closest canonical type so the frontend badge colors always resolve.
const TYPES = ['Thought Leadership','Event','Webinar','Campaign','Video','Award','Earned Media','Exec Commentary','Networking Event','Product','Partnership','Research','Positioning Shift','Funding','Distribution Tactic','Hiring','Milestone','Customer Story','Seasonal','Community','Interactive','Post'];
const ALIAS = { 'guide':'Thought Leadership','report':'Thought Leadership','blog':'Thought Leadership','ebook':'Thought Leadership','whitepaper':'Thought Leadership','conference':'Event','integration':'Partnership','ad':'Campaign','advertisement':'Campaign','podcast':'Video','rebrand':'Positioning Shift' };
function normType(t) {
  const s = String(t || '').trim();
  if (TYPES.includes(s)) return s;
  const a = ALIAS[s.toLowerCase()];
  if (a) return a;
  const hit = TYPES.find(x => x.toLowerCase() === s.toLowerCase());
  return hit || 'Post';
}
const outRows = [];
for (const s of selected) {
  let primaryIdx = s.primary_idx;
  if (primaryIdx == null) primaryIdx = Array.isArray(s.idx) ? s.idx[0] : s.idx;
  const p = byIdx.get(Number(primaryIdx));
  if (!p) continue;
  const taste_score = (tasteByIdx && tasteByIdx[primaryIdx] !== undefined) ? tasteByIdx[primaryIdx] : null;
  outRows.push({
    platform: 'LinkedIn',
    author: s.company || p.company,
    date: p.posted_at,
    url: p.url,
    source_id: p.source_id,
    summary: String(s.summary || ''),
    relevance_reason: String(s.relevance_reason || ''),
    strategic_angle: String(s.strategic_angle || ''),
    post_type: normType(s.post_type),
    collapsed_count: Math.max(1, Number(s.collapsed_count) || 1),
    reactions: p.reactions, comments: p.comments, reshares: p.reshares,
    period_start,
    taste_score,
  });
}
if (!outRows.length) return [{ json: { written: 0, candidates: posts.length, selected: selected.length } }];
let ok = false, errText = '';
try {
  await this.helpers.httpRequest({ method: 'POST', url: SB + '/posts_of_interest?on_conflict=platform,source_id', headers: H, body: outRows, json: true });
  ok = true;
} catch (e) { errText = String((e && e.message) || e).slice(0, 400); }
return [{ json: { written: ok ? outRows.length : 0, ok, candidates: posts.length, selected: selected.length, error: errText, period_start } }];

const base = $('Fetch Attributed Posts').first().json;
const posts = Array.isArray(base.posts) ? base.posts : [];

let embData = null;
try { embData = $('Embed Candidates').first().json.data; } catch (e) {}
if (!embData) { try { embData = $('Embed Candidates').first().json.body?.data; } catch (e) {} }

if (!embData || !Array.isArray(embData) || embData.length !== posts.length) {
  return [{ json: { ...base, tasteByIdx: {} } }];
}

const BASE = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY = '<REDACTED_SUPABASE_JWT>';
const headers = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };

const tasteByIdx = {};
const upSeen = [];
const downSeen = [];

for (let i = 0; i < posts.length; i++) {
  let emb = null;
  try { emb = embData[i].embedding; } catch (e) { emb = null; }
  if (!emb || !Array.isArray(emb)) { continue; }
  const embStr = '[' + emb.join(',') + ']';

  let neighbours = [];
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: BASE + '/rpc/match_poi_vectors',
      headers,
      body: { query_embedding: embStr, match_count: 8 },
      json: true,
    });
    if (Array.isArray(resp)) neighbours = resp;
    else if (resp && Array.isArray(resp.body)) neighbours = resp.body;
    else neighbours = [];
  } catch (e) { neighbours = []; }

  let num = 0, den = 0;
  for (const n of neighbours) {
    const sim = Number(n.similarity);
    if (!(sim >= 0.15)) continue;
    const sign = n.verdict === 'up' ? 1 : (n.verdict === 'down' ? -1 : 0);
    if (sign === 0) continue;
    num += sim * sign;
    den += sim;
    if (n.verdict === 'up') upSeen.push({ text: n.post_text, sim });
    else if (n.verdict === 'down') downSeen.push({ text: n.post_text, sim });
  }
  if (den > 0) {
    tasteByIdx[posts[i].idx] = Math.round((num / den) * 100) / 100;
  }
}

function topDistinct(arr) {
  arr.sort((a, b) => b.sim - a.sim);
  const seen = new Set();
  const out = [];
  for (const x of arr) {
    if (!x.text) continue;
    if (seen.has(x.text)) continue;
    seen.add(x.text);
    out.push(x.text);
    if (out.length >= 4) break;
  }
  return out;
}
const upEx = topDistinct(upSeen);
const downEx = topDistinct(downSeen);

function clip(t) { return (t || '').slice(0, 160); }

const origSys = base.openaiBody.messages[0].content;
let taste = '\n\n---\nTEAM TASTE — learned from the team\'s past 👍/👎 on these weekly digests. Treat as guidance, not a hard rule.\n';
if (upEx.length) {
  taste += 'Posts the team found INTERESTING (👍) looked like:\n';
  taste += upEx.map(t => '- "' + clip(t) + '"').join('\n') + '\n';
}
if (downEx.length) {
  taste += 'Posts they found NOT interesting (👎) looked like:\n';
  taste += downEx.map(t => '- "' + clip(t) + '"').join('\n') + '\n';
}
taste += 'Each candidate below also carries a "taste" hint in [-1..+1]: higher = more similar to past 👍 picks, negative = more like 👎. Prefer high-taste, genuinely novel posts; be skeptical of low or negative-taste posts unless clearly notable on their own merits.';
const augSystem = origSys + taste;

const promptPosts = posts.map(p => {
  const o = {
    idx: p.idx,
    company: p.company,
    posted_at: p.posted_at,
    reactions: p.reactions,
    comments: p.comments,
    reshares: p.reshares,
    is_reshare: p.is_reshare,
    text: p.text,
  };
  if (tasteByIdx[p.idx] !== undefined && tasteByIdx[p.idx] !== null) o.taste = tasteByIdx[p.idx];
  return o;
});

const openaiBody = {
  ...base.openaiBody,
  messages: [
    { role: 'system', content: augSystem },
    { role: 'user', content: 'Competitor posts from the past week (JSON):\n' + JSON.stringify(promptPosts) },
  ],
};

return [{ json: { period_start: base.period_start, count: base.count, posts: base.posts, openaiBody, tasteByIdx } }];
